#include <bits/stdc++.h>
using namespace std;
class Solution {public:int minimumMoves(vector<vector<int>>& grid){vector<pair<int,int>> extra,empty;for(int i=0;i<3;++i)for(int j=0;j<3;++j){if(grid[i][j]==0)empty.push_back({i,j});for(int c=1;c<grid[i][j];++c)extra.push_back({i,j});}int n=empty.size();vector<int> dp(1<<n,1000000);dp[0]=0;for(int mask=0;mask<(1<<n);++mask){int i=__builtin_popcount((unsigned)mask);if(i==n)continue;for(int j=0;j<n;++j)if(!(mask>>j&1))dp[mask|1<<j]=min(dp[mask|1<<j],dp[mask]+abs(extra[i].first-empty[j].first)+abs(extra[i].second-empty[j].second));}return dp[(1<<n)-1];}};
